116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        List<String> missingFields = new ArrayList<>();
120	        if (isBlank(ownerFieldsDto.getFirstName())) {
121	            missingFields.add("firstName");
122	        }
123	        if (isBlank(ownerFieldsDto.getLastName())) {
124	            missingFields.add("lastName");
125	        }
126	        if (isBlank(ownerFieldsDto.getAddress())) {
127	            missingFields.add("address");
128	        }
129	        if (isBlank(ownerFieldsDto.getCity())) {
130	            missingFields.add("city");
131	        }
132	        if (isBlank(ownerFieldsDto.getTelephone())) {
133	            missingFields.add("telephone");
134	        }
135	        if (!missingFields.isEmpty()) {
136	            throw new MissingOwnerFieldsException(missingFields);
137	        }
138	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
139	            String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
140	            String address = normalizeHousehold(ownerFieldsDto.getAddress());
141	            boolean householdInUse = this.clinicService.findAllOwners().stream()
142	                .anyMatch(existing -> lastName.equals(normalizeHousehold(existing.getLastName()))
143	                    && address.equals(normalizeHousehold(existing.getAddress())));
144	            if (householdInUse) {
145	                throw new DuplicateHouseholdException(
146	                    "an owner with the same last name and address already exists");
147	            }
148	        }
149	        String telephone = toE164(ownerFieldsDto.getTelephone());
150	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
151	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
152	        if (telephoneInUse) {
153	            throw new DuplicateTelephoneException(
154	                "an owner with the same E.164 telephone already exists");
155	        }
156	        ownerFieldsDto.setTelephone(telephone);
157	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
158	        HttpHeaders headers = new HttpHeaders();
159	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
160	        if (owner.getRegistrationDate() == null) {
161	            owner.setRegistrationDate(LocalDate.now());
162	        }
163	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
164	        this.clinicService.saveOwner(owner);
165	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
166	        headers.setLocation(UriComponentsBuilder.newInstance()
167	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
168	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
